// A newspaper's masthead above the scene it wraps: the paper's name, then a
// ruled line with today's date and the name of the scene.
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

export function get(app) {
  const { masthead, paperColor, inkColor } = app.state
  const now = new Date()
  const today = `${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]} ${now.getFullYear()}`
  return (
    <div className={`flex flex-col w-full h-full px-[3vw] bg-[${paperColor}] text-[${inkColor}]`}>
      <div className="flex items-center justify-center h-[13vh] text-[9vh] font-bold truncate">{masthead}</div>
      <div className={`flex items-center h-[5.5vh] gap-[2vw] text-[2.8vh] border-t-2 border-b-2 border-[${inkColor}]`}>
        <span className="flex-1 truncate">{today}</span>
        <span className="font-bold uppercase truncate">{app.frame.sceneName || ''}</span>
      </div>
      <div className="flex flex-col flex-1 min-h-0 py-[2vh]">
        <yield />
      </div>
    </div>
  )
}
